#include <cuda_fp16.h>

__global__ void cumulative_product_kernel(
    const half* input,
    half* output,
    int64_t total_elements,
    int64_t dim_size,
    int64_t stride,
    int64_t batch_size
) {
    int64_t batch_idx = blockIdx.x;
    if (batch_idx >= batch_size) return;

    const half* input_batch = input + batch_idx * dim_size * stride;
    half* output_batch = output + batch_idx * dim_size * stride;

    // For each element in the dimension we're cumulating along
    for (int64_t i = 0; i < dim_size; i++) {
        // Initialize with 1.0f for multiplication
        half prod = __float2half(1.0f);

        // Process elements from left to right
        for (int64_t j = 0; j <= i; j++) {
            // Calculate index for current element
            int64_t idx = j * stride;
            prod = __hmul(prod, input_batch[idx]);
        }

        // Store result
        int64_t out_idx = i * stride;
        output_batch[out_idx] = prod;
    }
}

